import pandas as pd

def kind_ok(series, kind):
    checks = {"int": pd.api.types.is_integer_dtype, "float": pd.api.types.is_float_dtype}
    return bool(checks[kind](series))

print(kind_ok(pd.Series([1, 2]), "int"))
print(kind_ok(pd.Series(["1", "2"]), "int"))
print(kind_ok(pd.Series([1.5, 2.5]), "float"))

