def change_kind(old_cols, new_cols):
    for name, spec in old_cols.items():
        if new_cols.get(name) != spec:
            return "breaking"
    added = [spec for name, spec in new_cols.items() if name not in old_cols]
    if any(not nullable for kind, nullable in added):
        return "breaking"
    return "compatible" if added else "none"

old = {"id": ("int", False), "note": ("string", True)}
print(change_kind(old, {**old, "channel": ("string", True)}))
print(change_kind(old, {"id": ("int", False), "memo": ("string", True)}))
print(change_kind(old, dict(old)))

