import pandas as pd

SCHEMA = {
    "id": {"kind": "int", "nullable": False},
    "amount": {"kind": "float", "nullable": False},
    "status": {"kind": "string", "nullable": False},
    "note": {"kind": "string", "nullable": True},
}

KINDS = {
    "int": pd.api.types.is_integer_dtype,
    "float": lambda s: pd.api.types.is_float_dtype(s) or pd.api.types.is_integer_dtype(s),
    "string": pd.api.types.is_object_dtype,
}

def check_schema(df, schema):
    problems = []
    for name, spec in schema.items():
        if name not in df.columns:
            problems.append(f"missing column {name}")
            continue
        if not KINDS[spec["kind"]](df[name]):
            problems.append(f"{name}: expected {spec['kind']}")
        nulls = int(df[name].isna().sum())
        if nulls and not spec["nullable"]:
            problems.append(f"{name}: {nulls} null(s)")
    problems.extend(f"unexpected column {c}" for c in df.columns if c not in schema)
    return problems

df = pd.DataFrame({"id": [1, 2, 3], "amount": ["5", "6", "7"], "status": ["paid", None, "failed"], "coupon": ["a", "b", "c"]})
problems = check_schema(df, SCHEMA)
print("\n".join(problems) if problems else "ok")

RECORDS = [
    {"order_id": 1, "amount_cents": 100, "status": "paid"},
    {"order_id": "2", "amount_cents": "250", "status": "failed"},
    {"order_id": "x", "amount_cents": -5, "status": "shipped"},
    {"order_id": 4, "status": "paid"},
    {"order_id": 5, "amount_cents": "1.5", "status": "refunded"},
]

def validate(rec):
    errors = []
    for name in ("order_id", "amount_cents"):
        if name not in rec:
            errors.append((name, "missing"))
            continue
        try:
            value = int(rec[name])
        except (TypeError, ValueError):
            errors.append((name, "int_parsing"))
            continue
        if name == "amount_cents" and value < 0:
            errors.append((name, "greater_than_equal"))
    if rec.get("status") not in {"paid", "refunded", "failed"}:
        errors.append(("status", "literal_error"))
    return errors

all_errors = [validate(r) for r in RECORDS]
invalid = sum(1 for e in all_errors if e)
print(f"valid={len(RECORDS) - invalid} invalid={invalid}")
counts = {}
for errs in all_errors:
    for field, kind in errs:
        counts[kind] = counts.get(kind, 0) + 1
print(sorted(counts.items()))
